<!-- @FIGURE_UI_BEGIN -->
<label>Initial N<sub>2</sub>O<sub>4</sub> concentration: <output id="initialN2O4Val">1.0</output><input id="initialN2O4Input" type="range" min="0.2" max="2" step="0.1" value="1" oninput="document.getElementById('initialN2O4Val').value=(+this.value).toFixed(1);update_initialN2O4(+this.value)"></label>
