// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 650, 920);

var W = 650, H = 920;
var red = '#c44a2a';
var redBright = '#ed1c24';
var blue = '#4f6db5';
var gray = '#808184';
var paleEq = '#f7edc7';
var axisColor = '#111';
var teq = 0.52;

var state = {
  initial: 1,
  quantity: 'Concentration',
  t: 0,
  step: 0
};

var topGroup = draw.group();
var graphGroup = draw.group();
var markerGroup = draw.group();
var badgeGroup = draw.group();

var redGrad = draw.gradient('radial', function(add) {
  add.stop(0, '#ff8888');
  add.stop(0.45, redBright);
  add.stop(1, '#b3191d');
});
var blueGrad = draw.gradient('radial', function(add) {
  add.stop(0, '#9fb2ea');
  add.stop(0.5, blue);
  add.stop(1, '#2f4d8f');
});

var demoSteps = [
  {
