    quantity: 'Concentration',
    initial: 1.6,
    t: 0.78
  }
];

function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

function progress(t) {
  if (t >= teq) return 1;
  return (1 - Math.exp(-5 * t)) / (1 - Math.exp(-5 * teq));
}

function valuesAt(t) {
  var p = progress(t);
  var n2o4 = state.initial * (1 - 0.68 * p);
  var no2 = state.initial * 1.25 * p;
  var fRate = 0.52 + 0.55 * (1 - p);
  var rRate = 0.52 * Math.pow(p, 0.92);
  if (t >= teq) {
    fRate = 0.52;
    rRate = 0.52;
  }
  return { p: p, n2o4: n2o4, no2: no2, fRate: fRate, rRate: rRate, eq: t >= teq };
}

function hexToRgb(h) {
  h = h.replace('#', '');
  return [parseInt(h.substr(0,2),16), parseInt(h.substr(2,2),16), parseInt(h.substr(4,2),16)];
}

function rgbToHex(r, g, b) {
  function c(x) {
    var s = Math.round(clamp(x,0,255)).toString(16);
    return s.length === 1 ? '0' + s : s;
  }
  return '#' + c(r) + c(g) + c(b);
}

function blend(a, b, t) {
  var A = hexToRgb(a), B = hexToRgb(b);
  return rgbToHex(A[0] + (B[0]-A[0])*t, A[1] + (B[1]-A[1])*t, A[2] + (B[2]-A[2])*t);
}

function addHaloText(parent, txt, x, y, size, anchor) {
  return parent.text(txt).font({
    family: 'Arial, Helvetica, sans-serif',
    size: size,
    anchor: anchor || 'middle'
  }).attr({
    x: x,
    y: y,
    'paint-order': 'stroke',
    stroke: '#fff',
    'stroke-width': 5,
    'stroke-linejoin': 'round'
  }).fill('#000');
}

function drawSphere(parent, x, y, r, fill) {
  parent.circle(2*r).center(x, y).fill(fill).stroke({ color: 'rgba(0,0,0,0.18)', width: 0.5 });
}

function rotPoint(x, y, a) {
  var c = Math.cos(a), s = Math.sin(a);
  return [x*c - y*s, x*s + y*c];
}

function molecule(parent, x, y, kind, scale, angle) {
  var g = parent.group();
  var a = (angle || 0) * Math.PI / 180;
  function place(dx, dy, r, fill) {
    var p = rotPoint(dx * scale, dy * scale, a);
    drawSphere(g, x + p[0], y + p[1], r * scale, fill);
  }
  function bond(dx1, dy1, dx2, dy2) {
    var p1 = rotPoint(dx1 * scale, dy1 * scale, a);
    var p2 = rotPoint(dx2 * scale, dy2 * scale, a);
    g.line(x+p1[0], y+p1[1], x+p2[0], y+p2[1]).stroke({ color: '#888', width: 2 * scale, linecap: 'round' }).back();
  }
  if (kind === 'dimer') {
    bond(-6, 0, 6, 0);
    bond(-6, 0, -12, -5);
    bond(-6, 0, -12, 5);
    bond(6, 0, 12, -5);
    bond(6, 0, 12, 5);
    place(-6, 0, 5.4, blueGrad);
    place(6, 0, 5.4, blueGrad);
    place(-13, -6, 5.8, redGrad);
    place(-13, 6, 5.8, redGrad);
    place(13, -6, 5.8, redGrad);
    place(13, 6, 5.8, redGrad);
  } else {
    bond(0, 0, -7, -5);
    bond(0, 0, 7, 4);
    place(0, 0, 5.3, blueGrad);
    place(-8, -6, 5.8, redGrad);
    place(8, 5, 5.8, redGrad);
  }
  g.css('cursor', 'pointer')
    .on('mousemove', function(e) {
      showTooltip(kind === 'dimer' ? 'N₂O₄ molecule: reactant dimer' : 'NO₂ molecule: product monomer', e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function() {
      showPopup(kind === 'dimer' ? 'N₂O₄' : 'NO₂',
        kind === 'dimer'
          ? 'N₂O₄ molecules can split to form NO₂. As N₂O₄ is consumed, the forward rate gradually falls.'
          : 'NO₂ molecules can combine to reform N₂O₄. As NO₂ accumulates, the reverse rate rises until it matches the forward rate.');
    });
  return g;
}

function drawTestTube(parent, cx, cy, color, angle) {
  var g = parent.group();
  var body = g.rect(22, 105).radius(11).center(cx, cy).fill(color).stroke({ color: '#b7b7b7', width: 1.4, opacity: 0.55 });
  var shine = g.line(cx - 5, cy - 44, cx - 5, cy + 34).stroke({ color: '#fff', width: 4, opacity: 0.28, linecap: 'round' });
  var lip = g.ellipse(25, 10).center(cx, cy - 52).fill(blend(color, '#ffffff', 0.18)).stroke({ color: '#b7b7b7', width: 1, opacity: 0.4 });
  g.rotate(angle, cx, cy);
  g.css('cursor', 'pointer')
    .on('mousemove', function(e) { showTooltip('Vial color deepens as NO₂ concentration increases.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function() {
      showPopup('Vial color', 'NO₂ is brown-orange, while N₂O₄ is nearly colorless. The visible color therefore tracks the amount of NO₂ present in the reacting mixture.');
    });
}

function drawArrow(parent, cx) {
  parent.path('M ' + (cx+28) + ' 132 C ' + (cx-12) + ' 158 ' + (cx-13) + ' 193 ' + (cx-6) + ' 211')
    .fill('none')
    .stroke({ color: '#111', width: 1.2 });
  parent.polygon([[cx-23,200],[cx+18,200],[cx-2,236]].map(function(p){ return p.join(','); }).join(' '))
    .fill('#f3f3f3')
    .stroke({ color: '#111', width: 1.2 });
}

var dimerSlots = [
  [-42,-28,15], [6,-40,-12], [44,-23,22], [-43,16,-20],
  [0,2,10], [42,23,-18], [-7,43,2], [-25,-3,35], [21,42,-28], [18,-7,12]
];
var monomerSlots = [
  [-52,-36,8], [-26,-48,18], [18,-48,-8], [51,-34,25],
  [-52,0,-18], [-18,-14,12], [17,-10,-8], [50,2,16],
  [-38,35,22], [-2,34,-12], [36,34,8], [5,10,0]
];

function drawSnapshot(parent, cx, label, tval, tubeColor, selected) {
  addHaloText(parent, label, cx, 32, 23, 'middle');
  drawTestTube(parent, cx, 85, tubeColor, -32);
  drawArrow(parent, cx);

  if (selected) {
    parent.rect(168, 204).center(cx, 258).radius(12).fill('none').stroke({ color: '#d8a900', width: 3, opacity: 0.65 });
  }

  parent.circle(154).center(cx, 302).fill('#f7f7f7').stroke({ color: gray, width: 4 });
  var mols = parent.group();
  var p = progress(tval);
  var dCount = Math.round((6 + state.initial * 1.6) * (1 - 0.43 * p));
  var mCount = Math.round((2 + state.initial * 5.5) * p);
  if (tval === 0) mCount = 0;
  for (var i = 0; i < Math.min(dCount, dimerSlots.length); i++) {
    var s = dimerSlots[i];
    molecule(mols, cx + s[0], 302 + s[1], 'dimer', 0.78, s[2]);
  }
  for (var j = 0; j < Math.min(mCount, monomerSlots.length); j++) {
    var q = monomerSlots[j];
    molecule(mols, cx + q[0], 302 + q[1], 'monomer', 0.72, q[2]);
  }
}

function renderTop() {
  topGroup.clear();
  var snapT = [0, 0.30, teq + 0.1];
  var nearest = 0;
  var best = 99;
  for (var i = 0; i < snapT.length; i++) {
    var dist = Math.abs(state.t - snapT[i]);
    if (dist < best) { best = dist; nearest = i; }
  }
  var colors = [
    '#d9d9ef',
    blend('#efd36c', '#c46b2e', clamp(0.25 + 0.25 * state.initial, 0, 0.55)),
    blend('#e88736', '#a94721', clamp(0.28 + 0.18 * state.initial, 0, 0.62))
  ];
  drawSnapshot(topGroup, 110, 't = 0', snapT[0], colors[0], nearest === 0);
  drawSnapshot(topGroup, 325, 'pre-equilibrium', snapT[1], colors[1], nearest === 1);
  drawSnapshot(topGroup, 540, 'at equilibrium', snapT[2], colors[2], nearest === 2);

  topGroup.line(126, 355, 178, 386).stroke({ color: '#111', width: 4, linecap: 'round' });
  addHaloText(topGroup, 'N₂O₄', 213, 403, 25, 'middle');
  topGroup.line(337, 365, 380, 393).stroke({ color: '#111', width: 4, linecap: 'round' });
  addHaloText(topGroup, 'NO₂', 413, 402, 25, 'middle');
  addHaloText(topGroup, '(a)', 325, 458, 24, 'middle');
}

var gx0 = 82, gy0 = 808, gw = 520, gh = 282;

function graphX(t) {
  return gx0 + t * gw;
}

function graphY(v, ymax) {
  return gy0 - (v / ymax) * gh;
}

function curvePoints(which, ymax) {
  var pts = [];
  for (var i = 0; i <= 160; i++) {
    var t = i / 160;
    var v = valuesAt(t);
    var yv;
    if (state.quantity === 'Concentration') {
      yv = which === 'blue' ? v.n2o4 : v.no2;
    } else {
      yv = which === 'blue' ? v.fRate : v.rRate;
    }
    pts.push([graphX(t), graphY(yv, ymax)]);
  }
  return pts.map(function(p){ return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' ');
}

function addAxisArrow(parent, x1, y1, x2, y2) {
  parent.line(x1, y1, x2, y2).stroke({ color: axisColor, width: 2.2, linecap: 'square' });
  if (x2 > x1) {
    parent.polygon((x2+1)+','+y2+' '+(x2-22)+','+(y2-8)+' '+(x2-22)+','+(y2+8)).fill(axisColor);
  } else {
    parent.polygon(x2+','+(y2-1)+' '+(x2-8)+','+(y2+23)+' '+(x2+8)+','+(y2+23)).fill(axisColor);
  }
}

function badge(parent, x, y, w, label, value, color) {
  var g = parent.group();
  g.rect(w, 31).move(x, y).radius(6).fill('#fff').stroke({ color: '#c8c8c8', width: 1 });
  g.text(label).font({ family: 'Arial', size: 9, anchor: 'start' }).attr({ x: x + 8, y: y + 8 }).fill('#555');
  g.text(value).font({ family: 'Arial', size: 13, weight: 'bold', anchor: 'start' }).attr({ x: x + 8, y: y + 23 }).fill(color || '#111');
  return g;
}

function renderGraph() {
  graphGroup.clear();
  badgeGroup.clear();
  markerGroup.clear();

  var ymax = state.quantity === 'Concentration'
    ? Math.max(1.55, state.initial * 1.36)
    : 1.16;

  graphGroup.rect(graphX(teq), gy0 - gh, graphX(0.97) - graphX(teq), gh)
    .fill(paleEq).opacity(0.85)
    .css('cursor', 'pointer')
    .on('mousemove', function(e) { showTooltip('After this line the macroscopic graph is flat: equilibrium has been achieved.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function() {
      showPopup('Equilibrium region', 'The shaded region begins when the opposing reaction rates have become equal. Concentrations remain constant there, even though molecules continue reacting in both directions.');
    });

  addAxisArrow(graphGroup, gx0, gy0, gx0, gy0 - gh - 22);
  addAxisArrow(graphGroup, gx0, gy0, gx0 + gw + 34, gy0);

  graphGroup.line(gx0, gy0, gx0, gy0 + 18).stroke({ color: axisColor, width: 2 });
  addHaloText(graphGroup, '0', gx0 + 23, gy0 + 45, 22, 'middle');
  addHaloText(graphGroup, 'Time', gx0 + gw/2, gy0 + 44, 24, 'middle');
  addHaloText(graphGroup, state.quantity, 29, gy0 - gh/2 + 10, 23, 'middle').rotate(-90, 29, gy0 - gh/2 + 10);

  var eqX = graphX(teq);
  graphGroup.line(eqX, gy0, eqX, gy0 - gh)
    .stroke({ color: '#111', width: 1.8, dasharray: '12 10' });

  var blueCurve = graphGroup.polyline(curvePoints('blue', ymax))
    .fill('none')
    .stroke({ color: blue, width: 5, linecap: 'round', linejoin: 'round' });
  var redCurve = graphGroup.polyline(curvePoints('red', ymax))
    .fill('none')
    .stroke({ color: red, width: 5, linecap: 'round', linejoin: 'round' });

  blueCurve.css('cursor', 'pointer')
    .on('mousemove', function(e) {
      showTooltip(state.quantity === 'Concentration' ? 'N₂O₄ concentration decreases and then levels off.' : 'Forward rate kf[N₂O₄] decreases as reactant is depleted.', e);
    })
    .on('mouseleave', hideTooltip);
  redCurve.css('cursor', 'pointer')
    .on('mousemove', function(e) {
      showTooltip(state.quantity === 'Concentration' ? 'NO₂ concentration increases and then levels off.' : 'Reverse rate kr[NO₂]² increases as product accumulates.', e);
    })
    .on('mouseleave', hideTooltip);

  if (state.quantity === 'Concentration') {
    addHaloText(graphGroup, 'NO₂', graphX(0.36), graphY(valuesAt(0.36).no2, ymax) - 24, 25, 'middle').fill('#000');
    addHaloText(graphGroup, 'N₂O₄', graphX(0.36), graphY(valuesAt(0.36).n2o4, ymax) + 28, 25, 'middle').fill('#000');
    addHaloText(graphGroup, 'Equilibrium\nachieved', graphX(0.75), graphY(valuesAt(0.75).no2 * 0.72, ymax), 23, 'middle');
  } else {
    addHaloText(graphGroup, 'kᶠ[N₂O₄]', graphX(0.16), graphY(valuesAt(0.16).fRate, ymax) - 18, 22, 'middle');
    addHaloText(graphGroup, 'kᵣ[NO₂]²', graphX(0.18), graphY(valuesAt(0.18).rRate, ymax) + 36, 22, 'middle');
    addHaloText(graphGroup, 'Equilibrium\nachieved', graphX(0.75), graphY(0.27, ymax), 23, 'middle');
  }

  addHaloText(graphGroup, state.quantity === 'Concentration' ? '(b)' : '(c)', 325, 884, 24, 'middle');

  drawMarker(ymax);
  renderBadges();
}

function renderBadges() {
  var v = valuesAt(state.t);
  badgeGroup.clear();
  badge(badgeGroup, 84, 480, 80, 'time', state.t.toFixed(2), '#111');
  badge(badgeGroup, 171, 480, 86, 'N₂O₄', v.n2o4.toFixed(2), blue);
  badge(badgeGroup, 264, 480, 78, 'NO₂', v.no2.toFixed(2), red);
