function clamp(v, a, b) {
  return Math.max(a, Math.min(b, v));
}

function progress(t) {
  if (t >= teq) return 1;
  return (1 - Math.exp(-5 * t)) / (1 - Math.exp(-5 * teq));
}

function valuesAt(t) {
  var p = progress(t);
  var n2o4 = state.initial * (1 - 0.68 * p);
  var no2 = state.initial * 1.25 * p;
  var fRate = 0.52 + 0.55 * (1 - p);
  var rRate = 0.52 * Math.pow(p, 0.92);
  if (t >= teq) {
    fRate = 0.52;
    rRate = 0.52;
  }
  return { p: p, n2o4: n2o4, no2: no2, fRate: fRate, rRate: rRate, eq: t >= teq };
}

function hexToRgb(h) {
  h = h.replace('#', '');
  return [parseInt(h.substr(0,2),16), parseInt(h.substr(2,2),16), parseInt(h.substr(4,2),16)];
}

function rgbToHex(r, g, b) {
  function c(x) {
    var s = Math.round(clamp(x,0,255)).toString(16);
    return s.length === 1 ? '0' + s : s;
  }
  return '#' + c(r) + c(g) + c(b);
}

