    bond(-6, 0, -12, -6);
    bond(-6, 0, -12, 6);
    bond(6, 0, 12, -6);
    bond(6, 0, 12, 6);
    atom(-6, 0, 5.3, blueGrad);
    atom(6, 0, 5.3, blueGrad);
    atom(-13, -7, 5.8, redGrad);
    atom(-13, 7, 5.8, redGrad);
    atom(13, -7, 5.8, redGrad);
    atom(13, 7, 5.8, redGrad);
