    bond(0, 0, -7, -5);
    bond(0, 0, 7, 5);
    atom(0, 0, 5.3, blueGrad);
    atom(-8, -6, 5.8, redGrad);
    atom(8, 6, 5.8, redGrad);
  }

  g.css('cursor', 'pointer')
    .on('mousemove', function(e) {
      showTooltip(kind === 'dimer' ? 'N₂O₄: a paired dimer that can split into two NO₂ molecules.' : 'NO₂: a brown-orange molecule that can recombine to form N₂O₄.', e);
