function easeToEq(t) {
  if (t >= eqT) return 1;
  return (1 - Math.exp(-6 * t)) / (1 - Math.exp(-6 * eqT));
}

function concN2O4(t) {
  var p = easeToEq(t);
  return 0.42 + 0.58 * (1 - p);
}

function concNO2(t) {
  var p = easeToEq(t);
  return 0.07 + 0.86 * p;
}

function rateForward(t) {
  var p = easeToEq(t);
  return 0.58 + 0.36 * (1 - p);
}

function rateReverse(t) {
  var p = easeToEq(t);
  return 0.08 + 0.50 * p;
}

function graphPath(xStart, y0, plotW, gh, fn, maxv) {
  var pts = [];
  for (var i = 0; i <= 180; i++) {
    var t = i / 180;
    var v = t >= eqT ? fn(eqT) : fn(t);
    pts.push([xStart + t * plotW, y0 - (v / maxv) * gh]);
  }
  return pts.map(function(p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' ');
}

function axisArrow(parent, x1, y1, x2, y2) {
  parent.line(x1, y1, x2, y2).stroke({ color: axisColor, width: 2.2, linecap: 'square' });
  if (x2 > x1) {
    parent.polygon((x2 + 1) + ',' + y2 + ' ' + (x2 - 23) + ',' + (y2 - 8) + ' ' + (x2 - 23) + ',' + (y2 + 8)).fill(axisColor);
  } else {
    parent.polygon(x2 + ',' + (y2 - 1) + ' ' + (x2 - 8) + ',' + (y2 + 24) + ' ' + (x2 + 8) + ',' + (y2 + 24)).fill(axisColor);
  }
}

